    public function settings(array $settings = null)
    {
        return $settings === null ? $this->getSettings() : $this->setSettings($settings);
    }

    public function mergeSettings(array $settings)
    {
        $this->settings = array_merge($this->settings, $settings);

        return $this;
    }

    /**
     * Round the given date at the given unit with given precision if specified and the given function.
     *
     * @param CarbonInterface $date
     * @param string          $unit
     * @param float|int       $precision
     * @param string          $function
     *
     * @return CarbonInterface
     */
    public function roundDateAtUnit(CarbonInterface $date, $unit, $precision = 1, $function = 'round')
    {
        $metaUnits = [
            'millennium' => [CarbonInterface::YEARS_PER_MILLENNIUM, 'year'],
            'century' => [CarbonInterface::YEARS_PER_CENTURY, 'year'],
            'decade' => [CarbonInterface::YEARS_PER_DECADE, 'year'],
            'quarter' => [CarbonInterface::MONTHS_PER_QUARTER, 'month'],
            'millisecond' => [1000, 'microsecond'],
        ];
        $normalizedUnit = $date::singularUnit($unit);
        $ranges = [
            'year' => [1, 9999],
            'month' => [1, CarbonInterface::MONTHS_PER_YEAR],
            'day' => [1, (int) $date->format('t')],
            'hour' => [0, CarbonInterface::HOURS_PER_DAY - 1],
            'minute' => [0, CarbonInterface::MINUTES_PER_HOUR - 1],
            'second' => [0, CarbonInterface::SECONDS_PER_MINUTE - 1],
            'microsecond' => [0, 999999],
        ];
        $factor = 1;
        $initialMonth = $date->month;
        $unitValues = [
            'year' => $date->year,
            'month' => $date->month,
            'day' => $date->day,
            'hour' => $date->hour,
            'minute' => $date->minute,
            'second' => $date->second,
            'microsecond' => $date->microsecond,
        ];

        if ($normalizedUnit === 'week') {
            $normalizedUnit = 'day';
            $precision *= CarbonInterface::DAYS_PER_WEEK;
        }

        if (isset($metaUnits[$normalizedUnit])) {
            [$factor, $normalizedUnit] = $metaUnits[$normalizedUnit];
        }

        $precision *= $factor;

        if (!isset($ranges[$normalizedUnit])) {
            throw new UnknownUnitException($unit);
        }

        $found = false;
        $fraction = 0;
        $arguments = null;
        $factor = $date->year < 0 ? -1 : 1;
        $changes = [];

        foreach ($ranges as $unit => [$minimum, $maximum]) {
            if ($normalizedUnit === $unit) {
                $arguments = [$unitValues[$unit], $minimum];
                $fraction = $precision - floor($precision);
                $found = true;

                continue;
            }

            if ($found) {
                $delta = $maximum + 1 - $minimum;
                $factor /= $delta;
                $fraction *= $delta;
                $arguments[0] += ($unitValues[$unit] - $minimum) * $factor;
                $changes[$unit] = round(
                    $minimum + ($fraction ? $fraction * $function(($unitValues[$unit] - $minimum) / $fraction) : 0)
                );

                // Cannot use modulo as it lose double precision
                while ($changes[$unit] >= $delta) {
                    $changes[$unit] -= $delta;
                }

                $fraction -= floor($fraction);
            }
        }

        [$value, $minimum] = $arguments;
        $normalizedValue = floor($function(($value - $minimum) / $precision) * $precision + $minimum);

        /** @var CarbonInterface $result */
        $result = $date->$normalizedUnit($normalizedValue);

        foreach ($changes as $unit => $value) {
            $result = $result->$unit($value);
        }

        if ($normalizedUnit === 'month' && $precision <= 1 && abs($result->month - $initialMonth) === 2) {
            $result = $result->$normalizedUnit($normalizedValue);
        }

        $className = $this->className;
        $settings = $this->settings;

        return $result instanceof $className && !empty($settings)
            ? $result->settings($settings)
            : $result;
    }

    public function __call($name, $arguments)
    {
        $method = new ReflectionMethod($this->className, $name);
        $settings = $this->settings;

        if ($settings && isset($settings['timezone'])) {
            $tzParameters = array_filter($method->getParameters(), function ($parameter) {
                return \in_array($parameter->getName(), ['tz', 'timezone'], true);
            });

            if (isset($arguments[0]) && \in_array($name, ['instance', 'make', 'create', 'parse'], true)) {
                if ($arguments[0] instanceof DateTimeInterface) {
                    $settings['innerTimezone'] = $settings['timezone'];
                } elseif (\is_string($arguments[0]) && date_parse($arguments[0])['is_localtime']) {
                    unset($settings['timezone'], $settings['innerTimezone']);
                }
            } elseif (\count($tzParameters)) {
                array_splice($arguments, key($tzParameters), 0, [$settings['timezone']]);
                unset($settings['timezone']);
            }
        }

        $result = $this->className::$name(...$arguments);

        return $result instanceof CarbonInterface && !empty($settings)
            ? $result->settings($settings)
            : $result;
    }
}

