$found = false;
$fraction = 0;
$fractionalValue = 0;
$arguments = null;
$factor = $date->year < 0 ? -1 : 1;
$changes = [];

foreach ($ranges as $unit => [$minimum, $maximum]) {
    if ($normalizedUnit === $unit) {
        $arguments = [$unitValues[$unit], $minimum];
        $fraction = $precision - floor($precision);
        $found = true;

        continue;
    }

    if ($found) {
        $delta = $maximum + 1 - $minimum;
        $factor /= $delta;
        $fraction *= $delta;
        $fractionalValue += ($unitValues[$unit] - $minimum) * $factor;
        $changes[$unit] = round(
            $minimum + ($fraction ? $fraction * $function(($unitValues[$unit] - $minimum) / $fraction) : 0)
        );

        // Cannot use modulo as it lose double precision
        while ($changes[$unit] >= $delta) {
            $changes[$unit] -= $delta;
        }

        $fraction -= floor($fraction);
    }
}

[$value, $minimum] = $arguments;
$base = ($value - $minimum) / $precision;
$fractional = $fractionalValue / $precision;
$integerPart = floor($base);
$fractionPart = $base - $integerPart;
$totalFraction = $fractionPart + $fractional;

if ($function === 'floor') {
    $normalized = $integerPart + floor($totalFraction);
} elseif ($function === 'ceil') {
    $normalized = $integerPart + ceil($totalFraction);
} elseif ($function === 'round') {
    if ($base + $fractional >= 0) {
        $normalized = $integerPart + round($totalFraction);
    } else {
        $ceiling = $integerPart + ceil($totalFraction);
        $normalized = $ceiling - round($ceiling - $base - $fractional);
    }
} else {
    $normalized = $function($base + $fractional);
}

$normalizedValue = floor($normalized * $precision + $minimum);

